    min_c = min(c[1] for c in cells)
    max_r = max(c[0] for c in cells)
    max_c = max(c[1] for c in cells)

    # Clockwise path: right across top, down right edge, left across bottom, up left edge
    path = []

    # Top bar (rightward)
    for c in range(min_c, max_c + 1):
        if grid[min_r][c] == 4:
            path.append((min_r, c))

    # Right edge (downward)
    for r in range(min_r + 1, max_r + 1):
        if grid[r][max_c] == 4:
            path.append((r, max_c))

    # Bottom bar (leftward)
    for c in range(max_c - 1, min_c - 1, -1):
        if grid[max_r][c] == 4:
            path.append((max_r, c))

    # Left edge (upward)
    for r in range(max_r - 1, min_r, -1):
        if grid[r][min_c] == 4:
            path.append((r, min_c))

    return path

